SELECT 
    (COUNT(CASE WHEN T1.dob < '1985-01-01' THEN T1.driverId END) * 100.0) / COUNT(T1.driverId) AS percentage
FROM 
    drivers AS T1
JOIN 
    results AS T2 ON T1.driverId = T2.driverId
WHERE 
    T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2000
    ) OR T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2001
    ) OR T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2002
    ) OR T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2003
    ) OR T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2004
    ) OR T2.raceId IN (
        SELECT raceId FROM races WHERE YEAR = 2005
    )
AND T2.lap > 50;

